Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  try { await Firebase.initializeApp(); } catch (_) {}
  final store = await Store.load();
  await store.connectFirebase();
  runApp(DainPayApp(store: store));
}

String makeId() => '${DateTime.now().microsecondsSinceEpoch}_${Random().nextInt(999999)}';
String money(double v) => '${v.toStringAsFixed(2)} د.ل';
String phone218(String value) { var p = value.replaceAll(RegExp(r'[^0-9]'), ''); if (p.startsWith('00')) p = p.substring(2); if (p.startsWith('218')) return p; if (p.startsWith('0')) return '218${p.substring(1)}'; return p; }
String dateText(DateTime d) => '${d.day.toString().padLeft(2,'0')}/${d.month.toString().padLeft(2,'0')}/${d.year}';

class Customer {
  Customer({required this.id, required this.name, required this.phone, this.limit = 0});
  String id, name, phone; double limit;
  Map<String,dynamic> toJson()=>{'id':id,'name':name,'phone':phone,'limit':limit};
  factory Customer.fromJson(Map<String,dynamic> j)=>Customer(id:'${j['id']??''}',name:'${j['name']??''}',phone:'${j['phone']??''}',limit:(j['limit'] as num?)?.toDouble()??0);
}
class Tx {
  Tx({required this.id,required this.customerId,required this.type,required this.amount,required this.date,required this.note,this.receiptPath='',this.receiptUrl=''});
  String id,customerId,type,note,receiptPath,receiptUrl; double amount; DateTime date;
  Map<String,dynamic> toJson()=>{'id':id,'customerId':customerId,'type':type,'amount':amount,'date':date.toIso8601String(),'note':note,'receiptPath':receiptPath,'receiptUrl':receiptUrl};
  factory Tx.fromJson(Map<String,dynamic> j)=>Tx(id:'${j['id']??''}',customerId:'${j['customerId']??''}',type:'${j['type']??'debt'}',amount:(j['amount'] as num?)?.toDouble()??0,date:DateTime.tryParse('${j['date']}')??DateTime.now(),note:'${j['note']??''}',receiptPath:'${j['receiptPath']??''}',receiptUrl:'${j['receiptUrl']??''}');
}

class Store extends ChangeNotifier {
  late SharedPreferences prefs;
  final customers=<Customer>[]; final transactions=<Tx>[];
  String shop='DainPay — دَيْن';
  String whatsappMessage='السلام عليكم [الاسم]، تذكير لطيف بخصوص المتبقي عليكم قدره [المبلغ] د.ل.';
  String uid='',deviceId=''; bool firebaseReady=false,syncing=false,activated=false; DateTime? trialStart;

  static Future<Store> load() async {
    final s=Store(); s.prefs=await SharedPreferences.getInstance();
    s.shop=s.prefs.getString('shop')??s.shop; s.whatsappMessage=s.prefs.getString('whatsappMessage')??s.whatsappMessage;
    s.deviceId=s.prefs.getString('device_id')??''; if(s.deviceId.isEmpty){s.deviceId='DP-${DateTime.now().millisecondsSinceEpoch}-${Random().nextInt(999999)}';await s.prefs.setString('device_id',s.deviceId);}
    final ts=s.prefs.getString('trial_start'); if(ts!=null) trialStart=DateTime.tryParse(ts); else {trialStart=DateTime.now();await s.prefs.setString('trial_start',trialStart!.toIso8601String());}
    s.activated=s.prefs.getBool('activated')??false;
    try{final d=jsonDecode(s.prefs.getString('customers')??'[]') as List;s.customers.addAll(d.map((e)=>Customer.fromJson(Map<String,dynamic>.from(e))));}catch(_){ }
    try{final d=jsonDecode(s.prefs.getString('transactions')??'[]') as List;s.transactions.addAll(d.map((e)=>Tx.fromJson(Map<String,dynamic>.from(e))));}catch(_){ }
    return s;
  }
  int get trialDaysLeft { if(activated||trialStart==null)return 0; return max(0,10-DateTime.now().difference(trialStart!).inDays); }
  bool get locked => !activated && trialDaysLeft<=0;
  Future<void> connectFirebase() async { try { var u=FirebaseAuth.instance.currentUser; u??=(await FirebaseAuth.instance.signInAnonymously()).user; if(u==null)return; uid=u.uid; firebaseReady=true; await pullCloud(); await loadActivation(); } catch(_){firebaseReady=false;} notifyListeners(); }
  CollectionReference<Map<String,dynamic>> get customersRef=>FirebaseFirestore.instance.collection('users').doc(uid).collection('customers');
  CollectionReference<Map<String,dynamic>> get transactionsRef=>FirebaseFirestore.instance.collection('users').doc(uid).collection('transactions');
  Future<void> loadActivation() async { if(!firebaseReady)return; try{final d=await FirebaseFirestore.instance.collection('device_activations').doc(deviceId).get(); if(d.exists&&d.data()?['activated']==true){activated=true;await prefs.setBool('activated',true);}}catch(_){}}
  Future<void> pullCloud() async { if(!firebaseReady||uid.isEmpty||syncing)return; syncing=true; try{for(final d in(await customersRef.get()).docs){final c=Customer.fromJson(d.data());final i=customers.indexWhere((x)=>x.id==c.id);if(i<0)customers.add(c);else customers[i]=c;}for(final d in(await transactionsRef.get()).docs){final x=d.data();final raw=x['date'];final dt=raw is Timestamp?raw.toDate():DateTime.tryParse('$raw')??DateTime.now();final t=Tx(id:'${x['id']??d.id}',customerId:'${x['customerId']??''}',type:'${x['type']??'debt'}',amount:(x['amount'] as num?)?.toDouble()??0,date:dt,note:'${x['note']??''}',receiptPath:'${x['receiptPath']??''}',receiptUrl:'${x['receiptUrl']??''}');final i=transactions.indexWhere((z)=>z.id==t.id);if(i<0)transactions.add(t);else transactions[i]=t;}await saveLocal();}catch(_){}finally{syncing=false;}}
  Future<void> saveCloud() async { if(!firebaseReady||uid.isEmpty||syncing)return; syncing=true; try{final b=FirebaseFirestore.instance.batch();for(final c in customers)b.set(customersRef.doc(c.id),c.toJson());for(final t in transactions)b.set(transactionsRef.doc(t.id),{...t.toJson(),'date':Timestamp.fromDate(t.date)});await b.commit();}catch(_){}finally{syncing=false;}}
  Future<void> saveLocal() async {await prefs.setString('customers',jsonEncode(customers.map((e)=>e.toJson()).toList()));await prefs.setString('transactions',jsonEncode(transactions.map((e)=>e.toJson()).toList()));await prefs.setString('shop',shop);await prefs.setString('whatsappMessage',whatsappMessage);}
  Future<void> save() async {await saveLocal();notifyListeners();await saveCloud();}
  double balance(String id)=>transactions.where((t)=>t.customerId==id).fold(0.0,(a,t)=>a+(t.type=='debt'?t.amount:-t.amount));
  double debts(String id)=>transactions.where((t)=>t.customerId==id&&t.type=='debt').fold(0.0,(a,t)=>a+t.amount);
  double paid(String id)=>transactions.where((t)=>t.customerId==id&&t.type=='payment').fold(0.0,(a,t)=>a+t.amount);
  String risk(String id){final b=balance(id);if(b<=0)return'مسدد';final ds=transactions.where((t)=>t.customerId==id&&t.type=='debt').toList()..sort((a,b)=>a.date.compareTo(b.date));if(ds.isEmpty)return'حديث';final d=DateTime.now().difference(ds.first.date).inDays;if(d>90)return'خطر';if(d>30)return'متأخر';return'حديث';}
  Future<bool> activate(String code) async { if(!firebaseReady||code.trim().isEmpty)return false; final ref=FirebaseFirestore.instance.collection('activation_codes').doc(code.trim()); try{final ok=await FirebaseFirestore.instance.runTransaction<bool>((tx)async{final snap=await tx.get(ref);final data=snap.data();if(!snap.exists||data==null||data['used']==true)return false;final bound='${data['deviceId']??''}';if(bound.isNotEmpty&&bound!=deviceId)return false;tx.update(ref,{'used':true,'usedAt':FieldValue.serverTimestamp(),'usedDeviceId':deviceId});return true;});if(!ok)return false;await FirebaseFirestore.instance.collection('device_activations').doc(deviceId).set({'activated':true,'activatedAt':FieldValue.serverTimestamp(),'uid':uid});activated=true;await prefs.setBool('activated',true);notifyListeners();return true;}catch(_){return false;}}
  Future<String?> generateCode(String targetDevice) async {if(!firebaseReady||targetDevice.trim().isEmpty)return null;String code;do{code=(100000+Random().nextInt(900000)).toString();}while((await FirebaseFirestore.instance.collection('activation_codes').doc(code).get()).exists);await FirebaseFirestore.instance.collection('activation_codes').doc(code).set({'deviceId':targetDevice.trim(),'used':false,'createdAt':FieldValue.serverTimestamp()});return code;}
}

