ListTile(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>CustomerPage(store:s,customer:c))),title:Text(c.name,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${c.phone}\n${s.risk(c.id)} • دين ${money(s.debts(c.id))} • مسدد ${money(s.paid(c.id))}'),isThreeLine:true,trailing:Text(money(b),style:const TextStyle(fontWeight:FontWeight.w900))));})]),floatingActionButton:FloatingActionButton.extended(onPressed:s.locked?()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ActivationPage(store:s))):()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AddCustomerPage(store:s))),icon:Icon(s.locked?Icons.lock_outline:Icons.person_add_alt_1),label:Text(s.locked?'التفعيل':'عميل')));}}
