class CustomerPage extends StatelessWidget{const CustomerPage({super.key,required this.store,required this.customer});final Store store;final Customer customer;Future<void> wa()async{final msg=store.whatsappMessage.replaceAll('[الاسم]',customer.name).replaceAll('[المبلغ]',money(store.balance(customer.id)));final u=Uri.https('wa.me','/${phone218(customer.phone)}',{'text':msg});if(await canLaunchUrl(u))await launchUrl(u,mode:LaunchMode.externalApplication);else await launchUrl(Uri.parse('https://wa.me/${phone218(customer.phone)}?text=${Uri.encodeComponent(msg)}'),mode:LaunchMode.externalApplication);}@override Widget build(BuildContext c){final items=store.transactions.where((t)=>t.customerId==customer.id).toList()..sort((a,b)=>b.date.compareTo(a.date));return Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(customer.name)),body:ListView(padding:const EdgeInsets.all(12),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Text('الرصيد'),Text(money(store.balance(customer.id)),style:const TextStyle(fontSize:30,fontWeight:FontWeight.w900)),Text('الدين ${money(store.debts(customer.id))} • المسدد ${money(store.paid(customer.id))}'),Wrap(spacing:8,children:[FilledButton.icon(onPressed:wa,icon:const Icon(Icons.chat),label:const Text('واتساب')),OutlinedButton.icon(onPressed:()=>launchUrl(Uri.parse('tel:${customer.phone}')),icon:const Icon(Icons.phone),label:const Text('اتصال'))])]))),...items.map((t)=>Card(child:ListTile(title:Text(t.type=='debt'?'دَين':'تسديد'),subtitle:Text('${dateText(t.date)}${t.note.isEmpty?'':' • ${t.note}'}'),leading:Icon(t.type=='debt'?Icons.arrow_downward:Icons.arrow_upward),trailing:Row(mainAxisSize:MainAxisSize.min,children:[if(t.receiptPath.isNotEmpty&&File(t.receiptPath).existsSync())IconButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ReceiptPage(path:t.receiptPath))),icon:const Icon(Icons.receipt_long_outlined)),Text(money(t.amount))]))))]),floatingA